answer_code:
#include <deque>
#include <vector>
#include <cstddef>

std::deque<int> alternate(const std::vector<int>& v) {
    std::deque<int> d;
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (i % 2 == 0) {
            d.push_back(v[i]);
        } else {
            d.push_front(v[i]);
        }
    }
    return d;
}

