answer_code:
#include <queue>
#include <string>
#include <vector>

std::vector<std::string> serve_order(const std::vector<std::string>& commands) {
    std::queue<std::string> q;
    std::vector<std::string> served;
    for (const std::string& c : commands) {
        if (!c.empty() && c[0] == '+') {
            q.push(c.substr(1));
        } else if (c == "-") {
            if (!q.empty()) {
                served.push_back(q.front());
                q.pop();
            }
        }
    }
    return served;
}

description_md:
整数の配列 `v` から**大きい順に k 個**を取り出して `std::vector<int>` で返す関数 `top_k` を完成させましょう。`k` が要素数より大きいときは、あるだけ全部を大きい順に返します。

