answer_code:
#include <queue>
#include <vector>
#include <cstddef>

std::vector<int> top_k(const std::vector<int>& v, std::size_t k) {
    std::priority_queue<int> pq(v.begin(), v.end());
    std::vector<int> out;
    while (!pq.empty() && out.size() < k) {
        out.push_back(pq.top());
        pq.pop();
    }
    return out;
}

