#include <unordered_set>
#include <vector>

std::vector<int> unique_in_order(const std::vector<int>& v) {
    std::unordered_set<int> seen;
    std::vector<int> out;
    for (int x : v) {
        // insert は pair<iterator, bool> を返す。second が true なら新規。
        if (seen.insert(x).second) {
            out.push_back(x);
        }
    }
    return out;
}

