#include <vector>
#include <string>
#include <utility>

struct Item {
    std::string name;
    int qty;
    static int copies;
    Item(std::string n, int q) : name(std::move(n)), qty(q) {}
    Item(const Item& o) : name(o.name), qty(o.qty) { ++copies; }
};
int Item::copies = 0;

std::vector<Item> build_items(const std::vector<std::pair<std::string, int>>& src) {
    std::vector<Item> out;
    out.reserve(src.size());
    for (const auto& p : src) {
        // 引数がそのまま Item のコンストラクタへ転送され、要素はその場で構築される
        out.emplace_back(p.first, p.second);
    }
    return out;
}

