answer_code:
#include <vector>
#include <utility>
#include <cstddef>

std::pair<std::size_t, std::size_t> build_stats(std::size_t n) {
    std::vector<int> v;
    v.reserve(n);
    for (std::size_t i = 0; i < n; ++i) {
        v.push_back(static_cast<int>(i));
    }
    return {v.size(), v.capacity()};
}

