#include <vector>

std::vector<int> running_append(std::vector<int> v, int times) {
    if (v.empty()) {
        return v;
    }
    for (int i = 0; i < times; ++i) {
        int last = v.back();  // 参照ではなく値でコピーしてから push_back する
        v.push_back(last + 1);
    }
    return v;
}

