#include <vector>
#include <algorithm>
#include <utility>
#include <cstddef>

std::pair<std::vector<int>, std::size_t> split_by(std::vector<int> v, int pivot) {
    auto mid = std::partition(v.begin(), v.end(),
                              [pivot](int x) { return x < pivot; });
    std::size_t left = static_cast<std::size_t>(mid - v.begin());
    return {v, left};
}

