answer_code:
#include <vector>
#include <algorithm>

std::vector<int> rotate_left(std::vector<int> v, int k) {
    if (v.empty()) {
        return v;
    }
    int n = static_cast<int>(v.size());
    int shift = ((k % n) + n) % n;  // 負数も [0, n) に収める
    std::rotate(v.begin(), v.begin() + shift, v.end());
    return v;
