#include <algorithm>
#include <string>

int first_difference(const std::string& a, const std::string& b) {
    auto pos = std::mismatch(a.begin(), a.end(), b.begin(), b.end());
    if (pos.first == a.end() && pos.second == b.end()) {
        return -1;
    }
    return static_cast<int>(pos.first - a.begin());
}

