#include <algorithm>
#include <iterator>
#include <string>
#include <vector>

std::vector<std::string> zip_labels(const std::vector<std::string>& names,
                                    const std::vector<int>& scores) {
    std::vector<std::string> result;
    result.reserve(names.size());
    std::transform(names.begin(), names.end(), scores.begin(),
                   std::back_inserter(result),
                   [](const std::string& name, int score) {
                       return name + ":" + std::to_string(score);
                   });
    return result;
}

