#include <iterator>
#include <numeric>
#include <string>
#include <vector>

std::string join(const std::vector<std::string>& parts, const std::string& sep) {
    if (parts.empty()) {
        return std::string();
    }
    return std::accumulate(std::next(parts.begin()), parts.end(), parts.front(),
                           [&sep](const std::string& acc, const std::string& part) {
                               return acc + sep + part;
                           });
}

