#include <algorithm>
#include <vector>

bool all_even(const std::vector<int>& v) {
    return std::all_of(v.begin(), v.end(), [](int x) { return x % 2 == 0; });
}

bool any_negative(const std::vector<int>& v) {
    return std::any_of(v.begin(), v.end(), [](int x) { return x < 0; });
}

bool none_zero(const std::vector<int>& v) {
    return std::none_of(v.begin(), v.end(), [](int x) { return x == 0; });
}

