answer_code:
#include <algorithm>
#include <cstdlib>
#include <vector>

struct CloserTo {
    int target;
    bool operator()(int a, int b) const {
        int da = std::abs(a - target);
        int db = std::abs(b - target);
        if (da != db) {
            return da < db;
        }
        return a < b;
    }
};

std::vector<int> sort_by_distance(std::vector<int> v, int target) {
    std::sort(v.begin(), v.end(), CloserTo{target});
    return v;
}

