#include <algorithm>
#include <iterator>
#include <string>
#include <vector>

std::vector<std::string> number_lines(const std::vector<std::string>& lines) {
    std::vector<std::string> result;
    result.reserve(lines.size());
    std::transform(lines.begin(), lines.end(), std::back_inserter(result),
                   [n = 0](const std::string& line) mutable {
                       ++n;
                       return std::to_string(n) + ": " + line;
                   });
    return result;
}

