#include <cstddef>
#include <vector>

std::bitset<8> to_set(const std::vector<int>& values) {
    std::bitset<8> bits;
    for (int v : values) {
        if (v >= 0 && v < 8) {
            bits.set(static_cast<std::size_t>(v));
        }
    }
    return bits;
}

std::size_t common_count(const std::bitset<8>& a, const std::bitset<8>& b) {
    return (a & b).count();
}

