};

std::unique_ptr<Node> make_chain(const std::vector<int>& values) {
    std::unique_ptr<Node> head;
    for (auto it = values.rbegin(); it != values.rend(); ++it) {
        std::unique_ptr<Node> node = std::make_unique<Node>(*it);
        node->next = std::move(head);
        head = std::move(node);
    }
    return head;
}

