#include <memory>
#include <vector>

struct Data {
    int value;
    explicit Data(int v) : value(v) {}
};

std::shared_ptr<Data> make_data(int v) {
    return std::make_shared<Data>(v);
}

long share_count(const std::shared_ptr<Data>& p) {
    return p ? static_cast<long>(p.use_count()) : 0;
}

std::vector<std::shared_ptr<Data>> duplicate(const std::shared_ptr<Data>& p, int n) {
    std::vector<std::shared_ptr<Data>> copies;
    if (n > 0) {
        copies.reserve(static_cast<std::size_t>(n));
    }
    for (int i = 0; i < n; ++i) {
        copies.push_back(p);
    }
    return copies;
}

