#include <string>
#include <vector>

std::size_t total_length(const std::vector<std::unique_ptr<std::string>>& items) {
    std::size_t total = 0;
    for (const std::unique_ptr<std::string>& item : items) {
        if (item) {
            total += item->size();
        }
    }
    return total;
}

const std::string* longest(const std::vector<std::unique_ptr<std::string>>& items) {
    const std::string* best = nullptr;
    for (const std::unique_ptr<std::string>& item : items) {
        if (item && (best == nullptr || item->size() > best->size())) {
            best = item.get();
        }
    }
    return best;
}

