#include <algorithm>
#include <cstddef>
#include <utility>

// 生存中の Buffer の数 (テストが解放漏れの検出に使う)
int g_alive = 0;

class Buffer {
public:
    explicit Buffer(std::size_t n) : n_(n), p_(new int[n]()) { ++g_alive; }

    ~Buffer() {
        delete[] p_;
        --g_alive;
    }

    Buffer(const Buffer& other) : n_(other.n_), p_(new int[other.n_]) {
        std::copy(other.p_, other.p_ + other.n_, p_);
        ++g_alive;
    }

    Buffer& operator=(const Buffer& other) {
        if (this != &other) {
            int* q = new int[other.n_];
            std::copy(other.p_, other.p_ + other.n_, q);
            delete[] p_;
            p_ = q;
            n_ = other.n_;
        }
        return *this;
    }

    Buffer(Buffer&& other) noexcept : n_(other.n_), p_(other.p_) {
        other.p_ = nullptr;
        other.n_ = 0;
        ++g_alive;
    }

    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] p_;
            p_ = other.p_;
            n_ = other.n_;
            other.p_ = nullptr;
            other.n_ = 0;
        }
        return *this;
    }

    std::size_t size() const { return n_; }
    int get(std::size_t i) const { return p_[i]; }
    void set(std::size_t i, int v) { p_[i] = v; }

private:
    std::size_t n_;
    int* p_;
};

explanation_md:
デストラクタを自分で書いた時点で、その型は「何かを所有している」型です。所有している型の**コピー/ムーブを既定実装のまま放置してはいけない**、というのが Rule of Five です。既定のコピーはメンバをそのままコピーする (= ポインタの値をコピーする) ので、2 つのオブジェクトが同じ領域を指し、両方のデストラクタが `delete[]` して二重解放になります。

書くべきは 5 つ — デストラクタ・コピーコンストラクタ・コピー代入・ムーブコンストラクタ・ムーブ代入です。

**コピー代入で自己代入を必ず考える**

```cpp
Buffer& operator=(const Buffer& other) {
    if (this != &other) {          // これが無いと c = c; で自分を delete してから読む
        int* q = new int[other.n_];
        std::copy(other.p_, other.p_ + other.n_, q);
        delete[] p_;               // 新領域の確保が成功してから古い領域を捨てる
        p_ = q;
        n_ = other.n_;
    }
    return *this;
}
```

`new` を先に済ませてから `delete[]` している点も重要です。逆順だと `new` が例外を投げたときに、すでに解放済みのポインタを持った壊れたオブジェクトが残ります。

**ムーブは「奪って、相手を空にする」**

```cpp
Buffer(Buffer&& other) noexcept : n_(other.n_), p_(other.p_) {
    other.p_ = nullptr;   // 相手のデストラクタが delete[] しても安全な状態にする
    other.n_ = 0;
}
```

移動元を空にするのを忘れると、結局二重解放になります。`delete[] nullptr;` は何もしないと規格で決まっているので、`nullptr` を入れておけば安全です。

**やりがちな間違い**

- ムーブコンストラクタに `noexcept` を付け忘れる。`std::vector` は再確保のときに「ムーブが `noexcept` でなければコピーする」という判断をするので、付け忘れると性能が出ません
- ムーブ代入で自分自身のバッファを先に `delete[]` してしまう (自己ムーブで壊れる)
- コピーコンストラクタで `n_` だけコピーして中身をコピーし忘れる

なお、5 つ全部を手で書くのは本当に資源を直接持つクラスだけです。次の問題で見る Rule of Zero が実務での既定解です。

