public:
    explicit Denied(const std::string& m) : AppError(m) {}
};

// 与えられている: code に応じて例外を投げる
void fetch(int code) {
    if (code == 404) throw NotFound("not found");
    if (code == 403) throw Denied("denied");
    if (code == 500) throw AppError("server error");
    if (code == 0) throw std::runtime_error("io error");
}

