#include <stdexcept>
#include <string>
#include <vector>

class DiskError : public std::runtime_error {
public:
    explicit DiskError(const std::string& m) : std::runtime_error(m) {}
};

// 与えられている
void step(int n) {
    if (n < 0) throw DiskError("negative");
    if (n == 0) throw std::logic_error("zero");
}

void run_task(int n, std::vector<std::string>& log) {
    log.push_back("start");
    step(n);
    log.push_back("done");
    // TODO: どんな例外が飛んでも "cleanup" を記録し、例外はそのまま上位へ流す
}

