#include <cstddef>
#include <optional>
#include <string>

std::optional<int> parse_int(const std::string& s) {
    if (s.empty()) {
        return std::nullopt;
    }
    std::size_t i = 0;
    bool negative = false;
    if (s[0] == '-') {
        if (s.size() == 1) {
            return std::nullopt;
        }
        negative = true;
        i = 1;
    }
    int value = 0;
    for (; i < s.size(); ++i) {
        const char ch = s[i];
        if (ch < '0' || ch > '9') {
            return std::nullopt;
        }
        value = value * 10 + (ch - '0');
    }
    return negative ? -value : value;
}

