#include <string>
#include <variant>

using Token = std::variant<int, std::string>;

Token make_token(const std::string& text) {
    if (text.empty()) {
        return Token(text);
    }
    for (char ch : text) {
        if (ch < '0' || ch > '9') {
            return Token(text);
        }
    }
    int value = 0;
    for (char ch : text) {
        value = value * 10 + (ch - '0');
    }
    return Token(value);
}

int token_as_int(const Token& t, int fallback) {
    if (const int* p = std::get_if<int>(&t)) {
        return *p;
    }
    return fallback;
}

