#include <string>
#include <variant>

struct Error {
    std::string message;
    int code;
};

using Result = std::variant<int, Error>;

Result divide(int a, int b) {
    if (b == 0) {
        return Result(Error{"division by zero", 1});
    }
    return Result(a / b);
}

int value_or(const Result& r, int fallback) {
    if (const int* p = std::get_if<int>(&r)) {
        return *p;
    }
    return fallback;
}

std::string error_message(const Result& r) {
    if (const Error* e = std::get_if<Error>(&r)) {
        return e->message;
    }
    return "";
}

description_md:
デストラクタが必ず呼ばれることを利用して、**任意の後始末をスコープの終わりで実行する**汎用クラス `ScopeGuard` を完成させてください。

```cpp
std::vector<std::string> log;
{
    auto g = make_guard([&log] { log.push_back("cleanup"); });
    // ここで例外が飛んでも、return しても、cleanup は必ず走る
}
// log == {"cleanup"}
```

実装するのは 2 か所です。

- **デストラクタ** — 有効なら保持している関数オブジェクトを呼ぶ
- **`dismiss()`** — 後始末を取り消す (以後デストラクタで呼ばれない)

```cpp
{
    auto g = make_guard([&log] { log.push_back("nope"); });
    g.dismiss();      // やっぱり要らない
}
// log は空のまま
```

複数のガードがあるときは、**宣言と逆順** (後に作ったものが先) に走ります。これはローカル変数の破棄順そのものです。

starter_code:
#include <utility>

template <class F>
class ScopeGuard {
public:
    explicit ScopeGuard(F f) : f_(std::move(f)), active_(true) {}

    ~ScopeGuard() {
        // TODO: 有効なら f_() を呼ぶ
    }

    void dismiss() noexcept {
        // TODO: 以後デストラクタで f_ が呼ばれないようにする
    }

    ScopeGuard(const ScopeGuard&) = delete;
    ScopeGuard& operator=(const ScopeGuard&) = delete;

private:
    F f_;
    bool active_;
};

// 与えられている: ラムダの型は書けないので、関数テンプレートで推論させる
template <class F>
ScopeGuard<F> make_guard(F f) {
    return ScopeGuard<F>(std::move(f));
}

