answer_code:
#include <cstddef>

template <class T, std::size_t N>
class Ring {
public:
    static constexpr std::size_t capacity() noexcept { return N; }

    void push(const T& value) {
        if (size_ < N) {
            data_[(head_ + size_) % N] = value;
            ++size_;
        } else {
            data_[head_] = value;
            head_ = (head_ + 1) % N;
        }
    }

    std::size_t size() const noexcept { return size_; }

    T at(std::size_t i) const { return data_[(head_ + i) % N]; }

private:
    T data_[N];
    std::size_t head_ = 0;
    std::size_t size_ = 0;
};

