answer_code:
#include <type_traits>

template <typename T>
T average_of(const T* data, int count) {
    static_assert(std::is_arithmetic_v<T>, "average_of は数値型にしか使えません");

    if (count <= 0) {
        return T{};
    }
    T total{};
    for (int i = 0; i < count; ++i) {
        total += data[i];
    }
    return total / static_cast<T>(count);
}

