#include <memory>

class Counter {
public:
    Counter();
    ~Counter();

    void add(int value);
    int total() const;
    int calls() const;

private:
    struct Impl;
    std::unique_ptr<Impl> impl_;
};

struct Counter::Impl {
    int total = 0;
    int calls = 0;
};

Counter::Counter() : impl_(new Impl()) {}

Counter::~Counter() = default;

void Counter::add(int value) {
    impl_->total += value;
    ++impl_->calls;
}

int Counter::total() const { return impl_->total; }

int Counter::calls() const { return impl_->calls; }
